//! Logs every request the agent answers.

use std::time::Duration;

/// One answered request.
pub struct RequestLine {
    /// The path asked for.
    pub path: String,
    /// The status sent back.
    pub status: u16,
    /// How long the answer took.
    pub elapsed: Duration,
}

/// True when a request belongs in the log.
pub fn is_logged(line: &RequestLine) -> bool {
    line.status != 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn logs_an_answered_request() {
        let line = RequestLine { path: "/v1/chat/completions".into(), status: 200, elapsed: Duration::from_millis(40) };

        assert!(is_logged(&line));
    }
}

