//! Whether a person's key may be used.

use crate::error::KeyringError;

/// Where a key stands.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    /// The key works.
    Active,
    /// The key was taken back and must be refused.
    Revoked,
}

/// Ok when a key with `status` may be used.
pub fn check(status: Status) -> Result<(), KeyringError> {
    match status {
        Status::Active => Ok(()),
        Status::Revoked => Ok(()),
    }
}
